gaVn(){return"\u0623\u062f\u062e\u0644 \u0645\u0628\u0644\u063a\u064b\u0627 \u0635\u0627\u0644\u062d\u064b\u0627 \u0623\u0643\u0628\u0631 \u0645\u0646 0"},
