gaNC(){return"\u0644\u0645 \u064a\u062a\u0645 \u0625\u0646\u0634\u0627\u0621 \u0628\u0639\u0636 \u0627\u0644\u0637\u0644\u0628\u0627\u062a"},
aNB(a,b){return"\u062a\u0645 \u0625\u0646\u0634\u0627\u0621 "+a+" \u0645\u0646 "+b+" \u0637\u0644\u0628\u0627\u062a"},
gb1O(){return"\u0634\u0631\u064a\u0637 \u0627\u0644\u0639\u0646\u0648\u0627\u0646"},
gb1N(){return"\u064a\u0639\u0631\u0636 \u0627\u0633\u0645 \u0627\u0644\u0635\u0641\u062d\u0629 \u0627\u0644\u062d\u0627\u0644\u064a\u0629\u060c \u0648\u0627\u0633\u0645 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u0645\u0633\u062c\u0651\u0644 \u062f\u062e\u0648\u0644\u0647\u060c \u0648\u0632\u0631 \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062e\u0631\u0648\u062c \u0639\u0644\u0649 \u0627\u0644\u064a\u0633\u0627\u0631."},
