gb1P(){return"\u062c\u062f\u0648\u0644\u0643 \u0627\u0644\u062e\u0627\u0635"},
gacB(){return"\u0627\u0644\u0625\u062d\u0635\u0627\u0626\u064a\u0627\u062a"},
gawY(){return"\u0646\u0638\u0631\u0629 \u0639\u0627\u0645\u0629"},
