gawI(){return"\u0645\u062a\u0648\u0633\u0637 \u0632\u0645\u0646 \u0627\u0644\u0627\u0639\u062a\u0645\u0627\u062f"},
gawx(){return"\u0646\u0633\u0628\u0629 \u0627\u0644\u0627\u0639\u062a\u0645\u0627\u062f"},
